

DELETE from role_resource where resourceid in (
select pgresourceid FROM pgresource WHERE resourceid IN (
	SELECT id FROM resource WHERE (lower(resourceid) LIKE 'cw-%' or 
	lower(resourceid) LIKE 'myintake-%' or lower(resourceid) LIKE 'caseworker-%')
)) and permissiontype = 1;

DELETE FROM pgresource WHERE resourceid IN (
	SELECT id FROM resource WHERE (lower(resourceid) LIKE 'cw-%' or 
	lower(resourceid) LIKE 'myintake-%' or lower(resourceid) LIKE 'caseworker-%')
);

DELETE FROM resource WHERE (lower(resourceid) LIKE 'cw-%' or 
	lower(resourceid) LIKE 'myintake-%' or lower(resourceid) LIKE 'caseworker-%');
	
	
